Promise.resolve('start')
  .then((value) => {
    console.log(value);
    throw new Error('boom');
  })
  .finally(() => console.log('finally-1'))
  .catch((error) => {
    console.log(error.message);
    return 'recovered';
  })
  .finally(() => {
    console.log('finally-2');
    throw new Error('cleanup');
  })
  .then(
    (value) => console.log(value),
    (error) => console.log(error.message),
  );
